// th18_s5_b4 — TH18 v1.00a Stage 5 关底 BossCard2（spell 48, BossCard2/BossCard2_Et/BossCard2_at）
// 源：st05bs.ecl.txt:683-829；上游判定 st05bs:28-29、中断 st05bs:711、开场 st05bs:719-722。
// 2026-11-07本会话用户明确接受恒宽近似：expand=20 的宽度增长提前到最终宽度，
// 下方laser()保留原危险时间窗，扩宽期提前20帧满宽；meta保留laser_approx=true，
// 此许可仅限本会话；完整机器验收及独立审核另行执行。

const TIME_LIMIT: int = 2824;      // 120 开场缓冲 + 2700 源中断 + 4 帧启动偏移余量
const OPENING_BUFFER: int = 120;

// Infinite 判定：len=0.9*512；w=16<32 → 半高 w/4=4 → 目标 width=8。
const LASER_LEN: fx = 460.8fx;
const LASER_W: fx = 8fx;
const CHILD_R: fx = 128fx;

// ---- 训练外壳（validation.md）：control 只管段事件，真实 Boss 在缓冲后创建。 ----
async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 1000, 0, 0, 0, boss_main); // 独立场景从 (0,128) 起
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

// ---- Boss 本体：移动配方复用 movement.md 的已核 moveRand 样本（mode0 速度、每帧限位）。 ----
// 本卡参数：x∈[-48,48]、y∈[96,160]；方向内区 x±24、y112..144。
sub boss_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -48fx { nx = -48fx; }
    if nx > 48fx { nx = 48fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub boss_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    boss_arm_next_step();
}

// 源 412 moveRand(60,4,1.0)：mode4 不覆盖速度槽，速度按 mode0 1→0。
sub boss_move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -24fx {
        a = r / 3;
    } else if $self_x > 24fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; } // 源右侧显式 wrap
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // ±π/2 的 0.05rad 护栏（源本卡整段不可达，保留配方）。
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    boss_begin_angle(a as angle);
}

sub boss_wait_until(frames: int, t_end: int) {
    for i in 0..frames {
        if $frame >= t_end { return; }
        wait(1);
        boss_arm_next_step();
    }
}

// ---- 每 260 帧一批 5 只子敌（源 730-765）；t=90 为 722 行时间门。 ----
sub burst(sign: int) {
    var phase: int = rand(65536); // 源 %RANDRAD：每批抽一次，5 只共用并逐只 +2π/5
    var omega: angle = 1deg;
    var offs: angle = 90deg;
    if sign < 0 { omega = 0deg - 1deg; offs = 0deg - 90deg; }
    var rank: int = global(GVAR_RANK);
    var nwait: int = 8;      // 源 817-825：E16/N9/H8/L8
    var startup: int = 40;   // 源 805-813：E60/N60/H50/L40
    if rank == 0 { nwait = 16; startup = 60; }
    else if rank == 1 { nwait = 9; startup = 60; }
    else if rank == 2 { nwait = 8; startup = 50; }
    var cx: fx = $self_x; // 子敌圆心 = 创建时父 FINAL
    var cy: fx = $self_y;
    for i in 0..5 {
        // 源 738-745：I0=2+2B，创建后 F0+=2π/5
        spawn child((phase + i * 65536 / 5) as angle, omega, offs, 2 + 2 * i,
                    cx, cy, nwait, startup);
    }
}

async sub boss_main() {
    set_invuln(65535);
    set_hitbox(24fx);  // 源 st05bs:29 setHitbox(48,48)
    set_hurtbox(20fx); // 源 st05bs:28 setHurtbox(40,40)
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT); // 源 719：从 (0,128) 到 (0,128)
    wait(90);                               // 源 722 的 +90 时间门
    var t_end: int = $frame + 2700;         // 源 711 setInterrupt(...,2700,"Boss3")
    var sign: int = 1;
    loop {
        burst(sign);
        boss_wait_until(200, t_end); // 源 747/766
        if $frame >= t_end { return; }
        boss_move_rand();            // 源 748/767
        boss_wait_until(60, t_end);  // 源 749/768
        if $frame >= t_end { return; }
        sign = -sign;
    }
}

// ---- 子敌：源 BossCard2_Et 779-791 + BossCard2_at 793-829 ----
// 源 flag303 = 0x2(禁体碰) | 0x4|0x8(跳过横/纵屏外回收)。子敌无体碰、无敌、不被查询，
// 故按 enemy-state.md §1/§3 的无交互发射体写成带独立世界坐标的任务，避开目标出界回收。
// 运动：圆心为创建时父 FINAL；半径 120 帧 0→128、保持到第 180 帧、再 120 帧回 0；
// 相位 θ=θ0+ω·t；激光角 = θ+F2（源 ABS_ANGLE+F2，不能用目标位移方向代替）。
async sub child(phase0: angle, omega: angle, offs: angle, color: int,
                cx: fx, cy: fx, nwait: int, startup: int) {
    var t: int = 0;
    var next_emit: int = 1; // 源 async 首跑 = 首次运动之后
    var r: fx = 0fx;
    loop {
        t = t + 1;
        if t > 300 { return; } // 源 Et 在 t=300 delete()
        if t <= 120 { r = CHILD_R * t / 120; }
        else if t <= 180 { r = CHILD_R; }
        else { r = CHILD_R * (300 - t) / 120; }
        var th: angle = ((phase0 as int) + ((omega as int) * t)) as angle;
        var px: fx = cx + r * cos(th);
        var py: fx = cy + r * sin(th);
        if t == next_emit {
            // 源 700/701/703：laserNew(...,512,512,0,16) + timing(startup,20,60,10)。
            // 本会话已获准：expand=20期间提前使用最终判定宽度8。
            _ = laser(color, px, py, th + offs, LASER_LEN, LASER_W, startup, 80, 10);
            next_emit = next_emit + nwait;
        }
        if t >= 300 { return; }
        wait(1);
    }
}
